// PRIMARY: crates/transaction-pool/src/validate/eth.rs:ensure_intrinsic_gas (lines 1196-1227)
pub fn ensure_intrinsic_gas<T: EthPoolTransaction>(
    transaction: &T,
    fork_tracker: &ForkTracker,
) -> Result<(), InvalidPoolTransactionError> {
    use revm_primitives::hardfork::SpecId;
    let spec_id = if fork_tracker.is_prague_activated() {
        SpecId::PRAGUE
    } else if fork_tracker.is_shanghai_activated() {
        SpecId::SHANGHAI
    } else {
        SpecId::MERGE
    };

    let gas = revm_interpreter::gas::calculate_initial_tx_gas(
        spec_id,
        transaction.input(),
        transaction.is_create(),
        ...
    );

    let gas_limit = transaction.gas_limit();
    if gas_limit < gas.initial_gas || gas_limit < gas.floor_gas {
        Err(InvalidPoolTransactionError::IntrinsicGasTooLow)
    } else {
        Ok(())
    }
}
// NOTE: EIP-7623 token counting (zero=1 token, nonzero=4 tokens) is implemented in
// revm_interpreter::gas::calculate_initial_tx_gas via floor_gas field

// PRIMARY: crates/transaction-pool/src/validate/eth.rs:ensure_intrinsic_gas (lines 1196-1227)
// floor_gas is returned by revm_interpreter::gas::calculate_initial_tx_gas
// EIP-7623: floor_gas = tokens * FLOOR_CALLDATA_COST(10) + TX_BASE_COST(21000)
// where tokens = sum(4 for nonzero bytes, 1 for zero bytes)
    if gas_limit < gas.initial_gas || gas_limit < gas.floor_gas {
        Err(InvalidPoolTransactionError::IntrinsicGasTooLow)
    } else {
        Ok(())
    }

