impl Decodable2718 for TransactionSigned {
    fn typed_decode(ty: u8, buf: &mut &[u8]) -> Eip2718Result<Self> {
        match ty.try_into().map_err(|_| Eip2718Error::UnexpectedType(ty))? {
            TxType::Legacy => Err(Eip2718Error::UnexpectedType(0)),
            TxType::Eip2930 => { let (tx, signature) = TxEip2930::rlp_decode_with_signature(buf)?; ... }
            TxType::Eip1559 => { let (tx, signature) = TxEip1559::rlp_decode_with_signature(buf)?; ... }
            TxType::Eip4844 => { let (tx, signature) = TxEip4844::rlp_decode_with_signature(buf)?; ... }
            TxType::Eip7702 => { let (tx, signature) = TxEip7702::rlp_decode_with_signature(buf)?; ... }
        }
    }
    fn fallback_decode(buf: &mut &[u8]) -> Eip2718Result<Self> {
        let (tx, signature) = TxLegacy::rlp_decode_with_signature(buf)?;
        Ok(Self { transaction: Transaction::Legacy(tx), signature, hash: Default::default() })
    }
}

