// NOTE: EIP-7702 set_code account destruction is handled in revm's state transition
// not in reth's direct codebase. Reth delegates EVM execution to revm.
// Closest code in reth:
// crates/transaction-pool/src/validate/eth.rs:validate_sender_bytecode (lines 564-596)
    pub fn validate_sender_bytecode(...) {
        if let Some(code_hash) = &sender.bytecode_hash {
            let is_eip7702 = if self.fork_tracker.is_prague_activated() {
                match state.bytecode_by_hash(code_hash) {
                    Ok(bytecode) => bytecode.unwrap_or_default().is_eip7702(),
                    ...
                }
            } else { false };
            if !is_eip7702 { return Ok(Err(InvalidTransactionError::SignerAccountHasBytecode.into())) }
        }
        Ok(Ok(()))
    }

